<?php
declare(strict_types=1);
// Synthetic fixtures only. Never print run nonces, cookies, or private configuration.
$file = __DIR__ . '/../server/Leaderboard.php';
if (!is_file($file)) { echo json_encode(['failed'=>1,'results'=>[['name'=>'ranking store exists','status'=>'FAIL']]]); exit(1); }
require $file;
use StarRebound\Leaderboard;
use StarRebound\ApiError;
$results=[];
function check(bool $value,string $message):void { if(!$value) throw new RuntimeException($message); }
function test(string $name,callable $fn):void { global $results;try{$fn();$results[]=['name'=>$name,'status'=>'PASS'];}catch(Throwable $e){$results[]=['name'=>$name,'status'=>'FAIL','message'=>$e->getMessage()];} }
$clock=1000.0;$db=new PDO('sqlite::memory:');$store=new Leaderboard($db,fn()=> $GLOBALS['clock']);
function resultFor(array $run,string $name='試験の星',int $score=0):array {return ['runId'=>$run['runId'],'nonce'=>$run['nonce'],'difficulty'=>$run['difficulty'],'ruleset'=>$run['ruleset'],'seed'=>$run['seed'],'name'=>$name,'score'=>$score,'time'=>2.0,'result'=>'lost','stageIndex'=>0,'completedStages'=>0,'hp'=>0,'kills'=>0,'returned'=>0,'bestCombo'=>0,'hits'=>2,'captureUses'=>0];}
test('issued runs fix positive seed, difficulty and ruleset',function()use($store){$r=$store->start(str_repeat('a',64),'nightmare');check($r['seed']>0,'seed must be positive');check($r['difficulty']==='nightmare','difficulty mismatch');check($r['ruleset']===Leaderboard::RULESET,'ruleset mismatch');check($r['expiresAt']===8200,'two hour wall-clock expiry');});
test('zero score registers once and duplicate finish is identical',function()use($store){$r=$store->start(str_repeat('b',64),'nightmare');$GLOBALS['clock']+=3;$p=resultFor($r);$a=$store->finish(str_repeat('b',64),$p);$b=$store->finish(str_repeat('b',64),$p);check($a===$b,'retry response changed');check(count($store->top('nightmare')['entries'])===1,'duplicate score rows');check($a['entry']['score']===0,'zero score missing');});
test('nonce reuse with a changed name is rejected',function()use($store){$r=$store->start(str_repeat('c',64),'nightmare');$GLOBALS['clock']+=3;$p=resultFor($r,'合成二号');$store->finish(str_repeat('c',64),$p);$p['name']='別の名前';try{$store->finish(str_repeat('c',64),$p);throw new RuntimeException('changed replay accepted');}catch(ApiError $e){check($e->status===409,'wrong rejection status');}});
test('same browser keeps a single best and lower scores preserve its name',function()use($store){$actor=str_repeat('d',64);$r=$store->start($actor,'nightmare');$GLOBALS['clock']+=3;$p=resultFor($r,'高い星',120);$p['kills']=1;$p['bestCombo']=1;$a=$store->finish($actor,$p);$r=$store->start($actor,'nightmare');$GLOBALS['clock']+=3;$b=$store->finish($actor,resultFor($r,'低い星'));check(!$b['improved'],'lower score improved');check($b['entry']['name']==='高い星','lower score replaced name');check($b['entry']['score']===120,'best score lost');});
test('foreign actor, altered rules and early elapsed time are rejected',function()use($store){$actor=str_repeat('e',64);$r=$store->start($actor,'nightmare');$p=resultFor($r);foreach(['foreign','rules','elapsed'] as $case){$q=$p;$who=$actor;if($case==='foreign')$who=str_repeat('f',64);if($case==='rules')$q['ruleset']='old';if($case==='elapsed')$q['time']=100;try{$store->finish($who,$q);throw new RuntimeException('invalid result accepted');}catch(ApiError $e){check(in_array($e->status,[400,403,409,422],true),'wrong validation status');}}});
test('names normalize spaces, count Unicode code points and reject controls',function(){check(Leaderboard::normalizeName('　試験　 星　')==='試験 星','space normalization');foreach(["",str_repeat('星',13),"星\n海",'<img>'] as $name){try{Leaderboard::normalizeName($name);throw new RuntimeException('bad name accepted');}catch(ApiError $e){check($e->status===422,'bad name status');}}});
test('top ten exposes only public fields and deterministic tie order',function()use($store){for($i=0;$i<12;$i++){$actor=hash('sha256','fixture'.$i);$r=$store->start($actor,'nightmare');$GLOBALS['clock']+=3;$store->finish($actor,resultFor($r,'合成'.$i));}$rows=$store->top('nightmare')['entries'];check(count($rows)===10,'top count');check($rows[0]['score']===120,'descending score');check($rows[1]['name']==='試験の星','earlier tie order');check(array_keys($rows[0])===['rank','name','score','stage','clear','details'],'private fields exposed');});
$failed=count(array_filter($results,fn($r)=>$r['status']==='FAIL'));echo json_encode(['failed'=>$failed,'results'=>$results],JSON_UNESCAPED_UNICODE|JSON_PRETTY_PRINT);exit($failed?1:0);
